n:1/-1;float:none;margin:0 0 2px}.food-menu-field:after,.payment-choice:after{content:"";display:block;clear:both}.food-menu-field .menu-heading{min-height:28px;align-items:start;margin-bottom:13px}.food-menu-field .menu-heading label{font-size:16px!important}.menu-heading>strong{font-size:18px!important}.reservation-menu{clear:both;display:grid!important;grid-template-columns:repeat(2,minmax(0,1fr));gap:7px!important;max-height:390px!important;margin-top:0!important;padding-right:3px}.reservation-category{grid-column:1/-1;position:static!important;margin:7px 0 0!important;padding:8px 10px!important;border-radius:6px!important;font-size:12px!important}.reservation-menu-item{grid-template-columns:54px minmax(0,1fr) 56px!important;min-height:72px;padding:8px!important;border:1px solid #e2e4dd;border-radius:7px!important;box-shadow:none!important}.reservation-menu-item img,.menu-placeholder{width:54px!important;height:54px!important;border-radius:6px!important}.reservation-menu-item b{font-size:14px}.reservation-menu-item small{font-size:11px}.reservation-menu-item span{font-size:13px}.menu-quantity{box-sizing:border-box;width:56px!important;height:42px;padding:7px!important;text-align:center;border-radius:7px!important}.payment-choice>label{display:block;margin:3px 0 9px;font-size:16px!important}.payment-choice>div:first-of-type{clear:both}.payment-choice>div>label{border-radius:7px!important;padding:12px!important;background:#fff}.payment-choice>div>label:has(input:checked){border-color:#8c960c;background:#f5f7e2}.gcash-qr{border-radius:7px!important}.proof-field{padding-top:16px!important}.booking-grid{display:grid!important;grid-template-columns:1fr 1fr!important;gap:12px 14px!important}.booking-grid .field{margin:0!important}.booking-grid label{font-size:13px}.booking-grid small{font-size:11px}.booking-grid textarea.control{min-height:76px;padding-top:11px;resize:vertical}.booking-button{position:static!important;min-height:48px!important;margin-top:2px!important;border-radius:7px!important;box-shadow:none!important;justify-content:center!important;gap:12px}.review-card{border-radius:8px!important}.review-lines{border-radius:7px!important;background:#f4f5ee!important}
@media(max-width:900px){.booking-form{padding:26px 18px 42px!important}.booking-heading h2{font-size:30px!important}.reservation-menu{grid-template-columns:1fr}.booking-grid{grid-template-columns:1fr!important}.booking-grid .full{grid-column:1!important}}
@media(max-width:520px){.booking-form{padding:22px 12px 36px!important}.booking-heading{margin-bottom:18px}.booking-heading h2{font-size:27px!important}.booking-types{grid-template-columns:1fr!important}.table-size-field,.food-menu-field,.payment-choice,.proof-field,.booking-grid{padding:14px!important}.payment-choice>div:first-of-type{grid-template-columns:1fr!important}.reservation-menu{max-height:350px!important}}
.booking-app-link b{display:none}.booking-app-link.disabled{opacity:.55;cursor:default;pointer-events:none}@media(max-width:900px){.booking-app-link span{display:none}.booking-app-link b{display:inline;font:inherit}}
.checkout-order-context{display:flex;align-items:center;justify-content:space-between;gap:18px;margin:0 0 18px;padding:15px 17px;border:1px solid #cbd39a;border-radius:8px;background:#f5f7df}.checkout-order-context>div{display:grid;gap:3px}.checkout-order-context span{color:#697200;font-size:10px;font-weight:900;letter-spacing:.12em}.checkout-order-context strong{font-size:16px}.checkout-order-context p{margin:0;color:#5f655b;font-size:13px;text-align:right}@media(max-width:620px){.checkout-order-context{display:grid}.checkout-order-context p{text-align:left}}
</style>

<script>(()=>{const types=document.querySelectorAll('input[name="type"]'),tableField=document.getElementById('table-size-field'),tableSelect=document.getElementById('table_size'),guestField=document.getElementById('guest-field'),guests=document.getElementById('guests'),quantities=[...document.querySelectorAll('.menu-quantity')],total=document.getElementById('menu-total'),money=n=>new Intl.NumberFormat('en-PH',{style:'currency',currency:'PHP'}).format(n);function updateTotal(){total.textContent=money(quantities.reduce((sum,input)=>sum+(+input.value||0)*(+input.dataset.price),0))}function update(){const isTable=document.querySelector('input[name="type"]:checked')?.value==='table';tableField.hidden=!isTable;tableSelect.required=isTable;guestField.hidden=isTable;guests.required=!isTable;if(!isTable)tableSelect.value='';if(isTable)guests.value='';updateTotal()}types.forEach(type=>type.addEventListener('change',update));quantities.forEach(input=>input.addEventListener('input',updateTotal));update()})();</script>
<div id="review-modal" class="review-modal" hidden><div class="review-card"><p class="eyebrow">REVIEW YOUR BOOKING</p><h2>Check all details</h2><div id="review-details" class="review-lines"></div><div id="review-qr" class="gcash-qr" hidden>GCash QR code<br><small>Add your QR image here</small></div><div class="review-actions"><button id="edit-booking" type="button">Edit details</button><button id="confirm-booking" class="confirm-booking" type="button">Confirm booking request</button></div></div></div>

<script>(()=>{const form=document.querySelector('.booking-inner form'),modal=document.getElementById('review-modal'),details=document.getElementById('review-details'),edit=document.getElementById('edit-booking'),confirm=document.getElementById('confirm-booking'),gcash=document.getElementById('gcash-qr'),reviewQr=document.getElementById('review-qr'),exclusiveFee={{ $exclusiveFee }},money=n=>new Intl.NumberFormat('en-PH',{style:'currency',currency:'PHP'}).format(n);let confirmed=false;function payment(){return form.querySelector('input[name="payment_method"]:checked')?.value||'cash'}function totals(){const type=form.querySelector('input[name="type"]:checked').value,option=document.getElementById('table_size').selectedOptions[0],fee=type==='table'?Number(option.dataset.fee||0):exclusiveFee,food=[...document.querySelectorAll('.menu-quantity')].reduce((s,i)=>s+(+i.value||0)*(+i.dataset.price),0);return{fee,food,total:fee+food}}function toggleQr(){gcash.hidden=payment()!=='gcash'}form.querySelectorAll('input[name="payment_method"]').forEach(i=>i.addEventListener('change',toggleQr));toggleQr();form.addEventListener('submit',event=>{if(confirmed)return;event.preventDefault();if(!form.reportValidity())return;const type=form.querySelector('input[name="type"]:checked').value,t=totals(),size=document.getElementById('table_size').value,date=document.getElementById('reservation_at').value,foods=[...document.querySelectorAll('.menu-quantity')].filter(i=>+i.value>0).map(i=>`${i.value} × ${i.closest('article').querySelector('b').textContent}`).join(', ')||'None';details.innerHTML=`<span><b>Reservation</b><strong>${type==='table'?size+'-seater table':'Exclusive venue'}</strong></span><span><b>Schedule</b><strong>${new Date(date).toLocaleString()}</strong></span><span><b>Phone</b><strong>${document.getElementById('phone').value}</strong></span><span><b>Food Request</b><strong>${foods}</strong></span><span><b>Reservation fee</b><strong>${money(t.fee)}</strong></span><span><b>Food total</b><strong>${money(t.food)}</strong></span><span><b>Total</b><strong>${money(t.total)}</strong></span><span><b>Payment</b><strong>${payment()==='cash'?'Walk In Pay':'GCash'}</strong></span>`;reviewQr.hidden=payment()!=='gcash';modal.hidden=false});edit.onclick=()=>modal.hidden=true;confirm.onclick=()=>{confirmed=true;form.requestSubmit()}})();</script>

<script>(()=>{const form=document.querySelector('.booking-inner form'),field=document.getElementById('proof-field'),input=document.getElementById('payment_proof'),reference=document.getElementById('payment_reference'),preview=document.getElementById('proof-preview'),methods=form.querySelectorAll('input[name="payment_method"]');form.enctype='multipart/form-data';function update(){const gcash=form.querySelector('input[name="payment_method"]:checked')?.value==='gcash';field.hidden=!gcash;input.required=gcash;reference.required=gcash;if(!gcash){input.value='';reference.value='';preview.hidden=true;preview.removeAttribute('src')}}methods.forEach(method=>method.addEventListener('change',update));reference.addEventListener('input',()=>reference.value=reference.value.replace(/\D/g,'').slice(0,13));input.addEventListener('change',()=>{const file=input.files[0];if(!file){preview.hidden=true;return}preview.src=URL.createObjectURL(file);preview.hidden=false});update()})();</script>









@endsection
